    {
      "component_id": "C1",
      "text": "In the thermal-ablation (TA) cohort, recurrence-free survival (RFS) was compared between model-stratified risk groups; among 688 enrolled patients with solitary HCC ≤ 5 cm undergoing CEUS before surgical resection (SR) or TA, patients with model-predicted high-risk MVI had significantly lower 1-, 2- and 3-year RFS rates (75.5%, 54.9%, 39.4%) compared with those with low-risk MVI (83.8%, 80.0%, 78.0%) (p < 0.001).",
      "cite": ["PMID:42047408"],
      "evidence_ids": ["E7", "E13", "E4"]
    },
    {
      "component_id": "C2",
      "text": "Cox regression analysis identified risk factors for RFS in TA patients, in whom high MVI risk predicted by the model (HR = 2.90; 95% CI: 1.69-4.96) and AFP-L3% (HR = 1.34; 95% CI: 1.06-1.69) were independently associated with RFS.",
      "cite": ["PMID:42047408"],
      "evidence_ids": ["E8", "E14"]
    }
  ],
  "confidence": 0.9,
  "evidence_status": "complete",
  "evidence_gap": ""
}

