{
  "claims": [
    {
      "component_id": "C1",
      "text": "In a study of 52 patients with adenomyosis with dysmenorrhea (AMD) and 52 age- and education-matched healthy controls (HCs) who underwent resting-state functional MRI, AMD patients showed significantly increased static and dynamic regional homogeneity (sReHo and dReHo) in the right fusiform gyrus (FFG; d = 0.84, p < 0.001) and significantly decreased sReHo and dReHo values in the bilateral supramarginal gyri (SMG; d = -0.73, p < 0.001) compared with HCs.",
      "cite": ["PMID:41614571"],
      "evidence_ids": ["E4", "E7"]
    },
    {
      "component_id": "C1",
      "text": "Additional regions exhibiting abnormal dReHo in AMD patients included the bilateral angular gyri, right hippocampus, right cerebellum (lobule 4_5), left middle frontal gyrus (MFG), and multiple subdivisions of the inferior frontal gyrus.",
      "cite": ["PMID:41614571"],
      "evidence_ids": ["E8"]
    },
    {
      "component_id": "C2",
      "text": "In partial correlation analyses controlling for medication use, menstrual phase and psychiatric history, ReHo in the right FFG of AMD patients positively correlated with pain severity on the visual analogue scale (VAS: r = 0.539-0.797, p < 0.001) and with anxiety on the Hamilton Anxiety Scale (HAMA: r = 0.442, p = 0.001).",
      "cite": ["PMID:41614571"],
      "evidence_ids": ["E6", "E9"]
    },
    {
      "component_id": "C2",
      "text": "Abnormalities in the right hippocampus and cerebellum were also significantly associated with anxiety and depression scores in AMD patients (r = 0.555-0.861, all p < 0.001).",
      "cite": ["PMID:41614571"],
      "evidence_ids": ["E10"]
    }
  ],
  "confidence": 0.9,
  "evidence_status": "complete",
  "evidence_gap": ""
}

{
  "claims": [
    {
      "component_id": "C1",
      "text": "This retrospective analytical cross-sectional study included 300 patients with epilepsy in Southern Kazakhstan, whose drug-resistance status was assigned by ILAE criteria into drug-sensitive (DSE) or drug-resistant groups, with data collected through clinical and socio-demographic evaluations, EEG and MRI assessments, and MoCA cognitive testing.",
      "cite": ["PMID:42057682", "PMC:doc54"],
      "evidence_ids": ["E4", "E20", "E5", "E21", "E22", "E23"]
    },
    {
      "component_id": "C1",
      "text": "The development of drug-resistant epilepsy became more likely when patients experienced their first seizure at a young age and when they had multiple seizures throughout the day (p < 0.01).",
      "cite": ["PMID:42057682"],
      "evidence_ids": ["E9"]
    },
    {
      "component_id": "C1",
      "text": "Key seizure-history correlates of drug-resistant epilepsy identified in the Southern Kazakhstan cohort were early age at onset, longer disease duration, frequent and severe seizures, and serial seizures; the study also reported that early seizure onset, prolonged duration, and severe seizures were related to drug resistance, alongside a substantially higher use of multiple antiseizure medications in the DRE group.",
      "cite": ["PMC:doc54", "PMID:42057682"],
      "evidence_ids": ["E14", "E11", "E16"]
    },
    {
      "component_id": "C2",
      "text": "In the same Southern Kazakhstan cohort, the presence of MRI abnormalities increased the risk of drug resistance by 2.42 times (95% CI: 1.3–4.23) when compared to drug-sensitive epilepsy patients (p = 0.002), and abnormal MRI findings were reported among the correlates of drug-resistant epilepsy.",
      "cite": ["PMID:42057682", "PMC:doc54"],
      "evidence_ids": ["E10", "E15", "E11"]
    }
  ],
  "confidence": 0.88,
  "evidence_status": "complete",
  "evidence_gap": ""
}

