      "evidence_ids": ["E5", "E6"]
    },
    {
      "component_id": "C1",
      "text": "Results demonstrated significantly elevated MTRasym values in the dentate nucleus and cerebellar hemisphere of PDRT patients (p<0.05), indicative of increased glutamate concentrations.",
      "cite": ["PMID:41687710"],
      "evidence_ids": ["E8"]
    },
    {
      "component_id": "C2",
      "text": "Cerebellar volumetry, derived using the SUIT atlas, showed that PDRT patients exhibited reduced cerebellar volumes compared to HCs, whereas PDAR patients showed no significant volumetric differences.",
      "cite": ["PMID:41687710"],
      "evidence_ids": ["E9", "E7"]
    }
  ],
